  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', iff(risky > 0, "#FF5C5C", "#83BA28"), ';color:', iff(risky > 0, "#FF5C5C", "#83BA28"), ';">', strcat(case(isnull(tolong(risky)), "0", tolong(risky) >= 1000000, strcat(round(tolong(risky) / 1000000.0, 1), "M"), tolong(risky) >= 1000, strcat(tolong(risky) / 1000, ",", substring(strcat("00", tolong(risky) % 1000), strlen(strcat("00", tolong(risky) % 1000)) - 3, 3)), tostring(tolong(risky))), " risky sign-ins"), '</span>'),
  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', iff(failPct > 20, "#F2B700", "#8FB0CF"), ';color:', iff(failPct > 20, "#F2B700", "#8FB0CF"), ';">', strcat(failPct, "% failed"), '</span>'),
  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', "#4FD1FF", ';color:', "#4FD1FF", ';">', strcat(case(isnull(tolong(invites)), "0", tolong(invites) >= 1000000, strcat(round(tolong(invites) / 1000000.0, 1), "M"), tolong(invites) >= 1000, strcat(tolong(invites) / 1000, ",", substring(strcat("00", tolong(invites) % 1000), strlen(strcat("00", tolong(invites) % 1000)) - 3, 3)), tostring(tolong(invites))), " invitations"), '</span>'),
  iff(spikes > 0, strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', "#FF5C5C", ';color:', "#FF5C5C", ';">', strcat(spikes, " unusual days, latest ", spikeDay), '</span>'), ""));
